document.addEventListener('DOMContentLoaded',function(){var swiper=new Swiper('.swiper-container',{slidesPerView:'auto',spaceBetween:10,grabCursor:true,navigation:{nextEl:'.swiper-button-next',prevEl:'.swiper-button-prev',},pagination:{el:'.swiper-pagination',clickable:true,},});});document.addEventListener('DOMContentLoaded',function(){document.addEventListener('click',function(e){if(e.target.classList.contains('Comment-onPost')){e.preventDefault();const post_id=e.target.getAttribute('data-id');const targetDiv=document.querySelector(`.PostComments-forPosts[data-id="${post_id}"]`);if(targetDiv){targetDiv.style.display=targetDiv.style.display==='block'?'none':'block';}}});});document.addEventListener('DOMContentLoaded',function(){document.addEventListener('click',function(e){if(e.target.classList.contains('Comment-Close')){e.preventDefault();const post_id=e.target.getAttribute('data-id');const targetDiv=document.querySelector(`.PostComments-forPosts[data-id="${post_id}"]`);if(targetDiv){targetDiv.style.display=targetDiv.style.display==='block'?'none':'block';}}});});document.addEventListener('DOMContentLoaded',function(){const userInput=document.getElementById('userInput');const progressCircle=document.querySelector('.image-mode-only .progress-circle .progress');const progressText=document.querySelector('.image-mode-only .progress-circle .text');const postButton=document.querySelector('.postButton');const moreWordsMessage=document.querySelector('.moreWords');let alertShown=false;let currentMode='image';const toggleButtons=document.querySelectorAll('.toggle-btn');toggleButtons.forEach(function(btn){btn.addEventListener('click',function(){currentMode=this.getAttribute('data-mode');});});if(userInput&&progressCircle){userInput.addEventListener('input',()=>{if(currentMode!=='image')return;const text=userInput.value.trim();const words=text.split(/\s+/).filter(word=>word.length>0);const wordCount=words.length;const progress=Math.min(wordCount/60*100,100);const offset=94.2-(94.2*progress/100);progressCircle.style.strokeDashoffset=offset;if(progressText){progressText.textContent=`${Math.floor(progress)}%`;}
if(progress>=100){progressCircle.classList.add('over-limit');}else{progressCircle.classList.remove('over-limit');}
if(progress>=100){postButton.style.display='none';}else{postButton.style.display='block';}
if(progress>=100){moreWordsMessage.style.display='block';}else{moreWordsMessage.style.display='none';}});userInput.addEventListener('keydown',(event)=>{if(currentMode!=='image')return;if(event.key==='Backspace'){const text=userInput.value.trim();const words=text.split(/\s+/).filter(word=>word.length>0);const wordCount=words.length;if(wordCount<=60){progressCircle.classList.remove('over-limit');postButton.style.display='block';moreWordsMessage.style.display='none';alertShown=false;}}});}});document.addEventListener('DOMContentLoaded',function(){const imageInput=document.getElementById('imageInput');const imageContainer=document.getElementById('preview');imageInput.addEventListener('change',function(){const file=this.files[0];if(file){const reader=new FileReader();reader.onload=function(e){imageContainer.style.display='block';imageContainer.querySelector('img').src=e.target.result;}
reader.readAsDataURL(file);}else{imageContainer.style.display='none';imageContainer.querySelector('img').src='';}});});function redirectToPath(path){window.location.href=path;}
document.addEventListener('DOMContentLoaded',function(){const openButtons=document.querySelectorAll('.open');const postDiv=document.querySelector('.PostContainers');const closeButton=postDiv.querySelector('.close');openButtons.forEach(function(openButton){openButton.addEventListener('click',function(){postDiv.style.display='block';});});closeButton.addEventListener('click',function(){if(confirm('Are you sure you want to discard the post?')){postDiv.style.display='none';}});});document.addEventListener('DOMContentLoaded',function(){const toggleButtons=document.querySelectorAll('.toggle-btn');const imageModeOnly=document.querySelectorAll('.image-mode-only');const confessionModeOnly=document.querySelectorAll('.confession-mode-only');const imageInput=document.getElementById('imageInput');const previewContainer=document.getElementById('preview');const userInput=document.getElementById('userInput');let currentMode='image';toggleButtons.forEach(function(btn){btn.addEventListener('click',function(){const mode=this.getAttribute('data-mode');if(mode===currentMode)return;toggleButtons.forEach(function(b){b.classList.remove('active');});this.classList.add('active');currentMode=mode;if(mode==='confession'){if(imageInput){imageInput.value='';}
if(previewContainer){previewContainer.style.display='none';previewContainer.querySelector('img').src='';}
imageModeOnly.forEach(function(el){el.classList.add('hidden');});confessionModeOnly.forEach(function(el){el.classList.remove('hidden');el.style.display='flex';});if(userInput){userInput.setAttribute('placeholder','Write your confession here...');}}else{imageModeOnly.forEach(function(el){el.classList.remove('hidden');});confessionModeOnly.forEach(function(el){el.classList.add('hidden');el.style.display='none';});if(userInput){userInput.setAttribute('placeholder','Something is in your mind? Say it here......');}}});});});document.addEventListener('DOMContentLoaded',function(){const userInput=document.getElementById('userInput');const progressCircle=document.querySelector('.confession-mode-only .progress');const progressText=document.querySelector('.confession-mode-only .text');const postButton=document.querySelector('.postButton');let currentMode='image';const toggleButtons=document.querySelectorAll('.toggle-btn');toggleButtons.forEach(function(btn){btn.addEventListener('click',function(){currentMode=this.getAttribute('data-mode');});});if(userInput&&progressCircle&&progressText){userInput.addEventListener('input',function(){if(currentMode!=='confession')return;const text=userInput.value;const charCount=text.length;const maxChars=250;const progress=Math.min((charCount/maxChars)*100,100);const dashOffset=94.2-(94.2*progress/100);progressCircle.style.strokeDashoffset=dashOffset;progressText.textContent=charCount+'/'+maxChars;if(progress>=100){progressCircle.style.stroke='#ff4444';postButton.disabled=true;postButton.style.opacity='0.5';}else{progressCircle.style.stroke='#667eea';postButton.disabled=false;postButton.style.opacity='1';}});}});;